#![cfg(not(target_family = "wasm"))]

//! Prove with key material generated by the unmodified Ledger 9.1.0.1 release.

use std::{
    borrow::Cow,
    io,
    sync::Arc,
    time::{Duration, Instant},
};

use base_crypto::data_provider::MidnightDataProvider;
use base_crypto::hash::HashOutput;
use coin_structure::contract::ContractAddress;
use ledger::{
    error::MalformedTransaction,
    structure::{ContractCall, ProofKind, ProofMarker, ProofVersioned},
    verify::ProofVerificationMode,
};
use midnight_curves::Bls12;
use midnight_proofs::{
    config::{ProverConfig, ProverContext},
    poly::kzg::params::ParamsKZG,
    utils::SerdeFormat,
};
use onchain_runtime::state::{ContractOperation, EntryPointBuf};
use rand::SeedableRng;
use rand_chacha::ChaCha20Rng;
use serialize::{tagged_deserialize, tagged_serialize};
use storage::db::InMemoryDB;
use transient_crypto::proofs::{
    CompanionCache, KeyLocation, MappedParams, ParamsProver, ParamsProverProvider, ParamsVerifier,
    Proof, ProofPreimage, ProverKey, ProvingKeyMaterial, Resolver, TrustedParamsDir, VerifierKey,
    Zkir,
};
use zkir_v3::IrSource;

const IR: &[u8] = include_bytes!("release-v3-9.1.0.1/ir.bin");
const PARAMS: &[u8] = include_bytes!("release-v3-9.1.0.1/params.bin");
const PK: &[u8] = include_bytes!("release-v3-9.1.0.1/prover-key.bin");
const VK: &[u8] = include_bytes!("release-v3-9.1.0.1/verifier-key.bin");
const PROOF: &[u8] = include_bytes!("release-v3-9.1.0.1/proof.bin");

#[test]
fn released_v3_proof_cannot_use_v2_contract_route() {
    let proof: Proof = tagged_deserialize(PROOF).expect("released V3 proof");
    let vk: VerifierKey = tagged_deserialize(VK).expect("released V3 verifier key");
    let v3_wire = tagged(&ProofVersioned::V3(proof.clone()));
    let v3_decoded: ProofVersioned =
        tagged_deserialize(v3_wire.as_slice()).expect("V3 proof envelope");
    assert!(matches!(v3_decoded, ProofVersioned::V3(_)));
    let operation = ContractOperation::new(Some(vk), None);
    let call = ContractCall::<ProofMarker, InMemoryDB> {
        address: ContractAddress(HashOutput([0; 32])),
        entry_point: EntryPointBuf(b"release-v3".to_vec()),
        guaranteed_transcript: None,
        fallible_transcript: None,
        communication_commitment: 0.into(),
        proof: ProofVersioned::V2(proof),
    };

    let wire = tagged(&call.proof);
    assert_ne!(wire, v3_wire, "V2 and V3 proof envelopes must differ");
    let decoded: ProofVersioned = tagged_deserialize(wire.as_slice()).expect("proof envelope");
    assert!(matches!(decoded, ProofVersioned::V2(_)));
    let error = <ProofMarker as ProofKind<InMemoryDB>>::proof_verify(
        &operation,
        &decoded,
        vec![42.into()],
        &call,
        ProofVerificationMode::Real,
    )
    .expect_err("V2 envelope must not use the V3 verifier key");
    assert!(matches!(
        error,
        MalformedTransaction::VerifierKeyNotPresent { address, operation }
            if address == call.address && operation == call.entry_point
    ));
}

struct ReleaseParams(ParamsProver);

impl ParamsProverProvider for ReleaseParams {
    async fn get_params(&self, _k: u8) -> io::Result<ParamsProver> {
        Ok(self.0.clone())
    }
}

struct ReleaseKeys;

struct NoFallback;

impl ParamsProverProvider for NoFallback {
    async fn get_params(&self, _k: u8) -> io::Result<ParamsProver> {
        panic!("released companion must be mapped without a heap fallback")
    }
}

impl Resolver for ReleaseKeys {
    async fn resolve_key(&self, key: KeyLocation) -> io::Result<Option<ProvingKeyMaterial>> {
        assert_eq!(key.0.as_ref(), "release-v3");
        Ok(Some(ProvingKeyMaterial {
            prover_key: PK.to_vec(),
            verifier_key: VK.to_vec(),
            ir_source: IR.to_vec(),
        }))
    }
}

#[actix_web::test]
async fn released_v3_proof_and_key_remain_usable() {
    let ir: IrSource = tagged_deserialize(&mut &IR[..]).expect("released IR");
    let pk: ProverKey<IrSource> = tagged_deserialize(&mut &PK[..]).expect("released prover key");
    let vk: VerifierKey = tagged_deserialize(&mut &VK[..]).expect("released verifier key");
    let proof: Proof = tagged_deserialize(&mut &PROOF[..]).expect("released proof");
    for (actual, expected) in [
        (tagged(&ir), IR),
        (tagged(&pk), PK),
        (tagged(&vk), VK),
        (tagged(&proof), PROOF),
    ] {
        assert_eq!(actual, expected, "released serialization roundtrip");
    }
    assert!(tagged_deserialize::<Proof>(&mut &PROOF[..PROOF.len() - 1]).is_err());
    assert!(tagged_deserialize::<ProverKey<IrSource>>(&mut &PK[..PK.len() - 1]).is_err());
    let verifier_params = ParamsVerifier::read(PARAMS).expect("released verifier params");
    vk.verify(&verifier_params, &proof, [42.into()].into_iter())
        .expect("released proof verifies with released key");
    assert!(
        vk.verify(&verifier_params, &proof, [43.into()].into_iter())
            .is_err()
    );

    let prover_params =
        ParamsKZG::<Bls12>::read_custom(&mut &PARAMS[..], SerdeFormat::RawBytesUnchecked)
            .expect("released prover params");
    let params = ReleaseParams(ParamsProver(Arc::new(prover_params)));
    let preimage = ProofPreimage {
        binding_input: 42.into(),
        communications_commitment: None,
        inputs: vec![1.into()],
        private_transcript: vec![],
        public_transcript_inputs: vec![],
        public_transcript_outputs: vec![],
        key_location: KeyLocation(Cow::Borrowed("release-v3")),
    };
    let (bench_arm, repetitions) = benchmark_arm();
    let mut heap_proof = None;
    if bench_arm != Some("mapped") {
        let mut elapsed = Duration::ZERO;
        for _ in 0..repetitions {
            let start = Instant::now();
            let (proof, _) = preimage
                .prove_with_context::<IrSource>(
                    ChaCha20Rng::from_seed([42; 32]),
                    &params,
                    &ReleaseKeys,
                    &ProverContext::new(ProverConfig::heap()),
                )
                .await
                .expect("current branch proves with released key material");
            elapsed += start.elapsed();
            vk.verify(&verifier_params, &proof, [42.into()].into_iter())
                .expect("released verifier key accepts current proof");
            heap_proof = Some(proof);
        }
        if bench_arm.is_some() {
            eprintln!(
                "release-v3 k={} arm=heap repetitions={repetitions} prove_ms={:.3}",
                ir.k(),
                elapsed.as_secs_f64() * 1_000.0
            );
        }
    }

    if bench_arm != Some("heap") {
        let dir = tempfile::tempdir().expect("private companion directory");
        // This test alone owns the directory. The cache publishes its companion
        // without clobbering and no writer can alter it while the mapping lives.
        let trusted = unsafe { TrustedParamsDir::new(dir.path()) };
        let cache = CompanionCache::from_trusted_dir(trusted.clone());
        cache
            .open_or_build(&MidnightDataProvider::name_k(ir.k()), || {
                Ok(params.0.clone())
            })
            .expect("publish released parameters as an immutable companion");
        let mapped = MappedParams::new(NoFallback, trusted);
        let mut policy = ProverConfig::mapped_key_and_cosets();
        policy.coset_spill_floor_k = 0;
        policy.spill_dir = Some(
            std::env::var_os("MIDNIGHT_RELEASE_BENCH_SPILL_DIR")
                .map(std::path::PathBuf::from)
                .unwrap_or_else(|| dir.path().to_path_buf()),
        );
        assert!(policy.spills_cosets_at(ir.k() as u32));
        let mut elapsed = Duration::ZERO;
        for _ in 0..repetitions {
            let start = Instant::now();
            let (proof, _) = preimage
                .prove_with_context::<IrSource>(
                    ChaCha20Rng::from_seed([42; 32]),
                    &mapped,
                    &ReleaseKeys,
                    &ProverContext::new(policy.clone()),
                )
                .await
                .expect("released key proves with mapped parameters and forced spill");
            elapsed += start.elapsed();
            vk.verify(&verifier_params, &proof, [42.into()].into_iter())
                .expect("released verifier key accepts mapped and spilled proof");
            if let Some(heap_proof) = &heap_proof {
                assert_eq!(heap_proof, &proof, "proof bytes must be policy independent");
            }
        }
        if bench_arm.is_some() {
            eprintln!(
                "release-v3 k={} arm=mapped repetitions={repetitions} prove_ms={:.3}",
                ir.k(),
                elapsed.as_secs_f64() * 1_000.0
            );
        }
    }
}

fn benchmark_arm() -> (Option<&'static str>, usize) {
    let arm = match std::env::var("MIDNIGHT_RELEASE_BENCH_ARM").as_deref() {
        Ok("heap") => Some("heap"),
        Ok("mapped") => Some("mapped"),
        Err(_) => None,
        _ => panic!("MIDNIGHT_RELEASE_BENCH_ARM must be heap or mapped"),
    };
    let repetitions = if arm.is_some() {
        std::env::var("MIDNIGHT_RELEASE_BENCH_REPETITIONS")
            .unwrap_or_else(|_| "1".into())
            .parse::<usize>()
            .expect("positive benchmark repetitions")
    } else {
        1
    };
    assert!(repetitions > 0);
    (arm, repetitions)
}

fn tagged<T: serialize::Serializable + serialize::Tagged>(value: &T) -> Vec<u8> {
    let mut bytes = Vec::new();
    tagged_serialize(value, &mut bytes).expect("serialize fixture");
    bytes
}
